   <div v-if="['colors','semantic'].includes(group.id)" class="swatch-grid"><article v-for="token in group.tokens" :key="token.name" class="swatch-card"><div class="color-swatch" :style="{backgroundColor:token.value}" aria-hidden="true"></div><div class="swatch-description"><code>{{ token.name }}</code><span>{{ token.value }}</span><p>{{ token.usage }}</p></div></article></div>
